from dataclasses import dataclass, field
from flow_autotts.controllers.optimal import OptimalController
from flow_autotts.core.errors import BudgetExceededError, InvalidActionError
from flow_autotts.core.state import AnswerRecord, ControllerState, EventRecord, ParticleSummary, PreviewRecord

@dataclass
class Particle:
    id:int
    time:float=0.0
    status:str='active'
    last_preview_id:int|None=None
    parent_id:int|None=None
    source_anchor_id:int|None=None
    num_children:int=0
    nfe_used:int=0

class FakeEnv:
    def __init__(self,budget=64,steps=10):
        self.budget=budget
        self._nfe=0
        self.time_grid=tuple(i/steps for i in range(steps+1))
        self._particles={}
        self._previews={}
        self._events=[]
        self._next_pid=0
        self._next_aid=0
        self._answered=False
    @property
    def budget_left(self):
        return self.budget-self._nfe
    def spawn(self,n):
        if n<=0: raise InvalidActionError('bad spawn')
        ids=[]
        for _ in range(n):
            pid=self._next_pid; self._next_pid+=1
            self._particles[pid]=Particle(id=pid)
            ids.append(pid)
        return ids
    def forward(self,particle_id,target_time,solver='euler',cfg=None):
        p=self._particles[particle_id]
        if p.status"'!='"'active': raise InvalidActionError('inactive')
        step0=self.time_grid.index(round(p.time,10)) if round(p.time,10) in [round(t,10) for t in self.time_grid] else min(range(len(self.time_grid)), key=lambda i: abs(self.time_grid[i]-p.time))
        step1=min(range(len(self.time_grid)), key=lambda i: abs(self.time_grid[i]-target_time))
        if step1<=step0: raise InvalidActionError('non-advancing')
        cost=step1-step0
        if self._nfe+cost>self.budget: raise BudgetExceededError
        self._nfe+=cost
        p.time=self.time_grid[step1]
        p.nfe_used+=cost
        if step1==len(self.time_grid)-1: p.status='completed'
        return self.get_state().particles[particle_id]
    def preview(self,particle_id,mode='clean_anchor',scorer='default'):
        p=self._particles[particle_id]
        if p.status=='pruned': raise InvalidActionError('pruned')
        if self._nfe+1>self.budget: raise BudgetExceededError
        self._nfe+=1
        aid=self._next_aid; self._next_aid+=1
        score=0.1 + 0.8*p.time + (particle_id % 3)*0.01 - p.num_children*0.005
        uncertainty=max(0.0, 0.6 - 0.5*p.time)
        prev=PreviewRecord(id=aid, particle_id=particle_id, time=p.time, score=score, uncertainty=uncertainty, score_dict={})
        self._previews[aid]=prev
        p.last_preview_id=aid
        p.nfe_used+=1
        return prev
    def backward(self,anchor_id,target_time,noise_policy='fresh_noise',num_children=1,mask=None,strength=1.0):
        if num_children<=0: raise InvalidActionError('bad child count')
        if mask is not None: raise InvalidActionError('mask unsupported')
        anchor=self._previews[anchor_id]
        parent=self._particles[anchor.particle_id]
        ids=[]
        for _ in range(num_children):
            pid=self._next_pid; self._next_pid+=1
            self._particles[pid]=Particle(id=pid,time=target_time,parent_id=parent.id,source_anchor_id=anchor_id)
            ids.append(pid)
        parent.num_children += num_children
        return ids
    def prune(self,particle_ids):
        for pid in particle_ids:
            p=self._particles[pid]
            if p.status=='completed': raise InvalidActionError('cannot prune completed')
            p.status='pruned'
    def answer(self,rule='best_preview_score'):
        self._answered=True
        if rule=='best_preview_score' and self._previews:
            best=max(self._previews.values(), key=lambda x:x.score)
            return AnswerRecord(particle_id=best.particle_id, preview_id=best.id, latent=(), reward=best.score, nfe_used=self._nfe, rule=rule, event_log=[], score_dict={})
        active=[p for p in self._particles.values() if p.status in {'active','completed'}]
        if not active:
            return AnswerRecord(particle_id=None, preview_id=None, latent=(), reward=None, nfe_used=self._nfe, rule=rule, event_log=[], score_dict={})
        chosen=max(active, key=lambda p:(p.time,p.id))
        if chosen.status=='active':
            self.forward(chosen.id,1.0,'euler')
        return AnswerRecord(particle_id=chosen.id, preview_id=chosen.last_preview_id, latent=(), reward=chosen.time, nfe_used=self._nfe, rule=rule, event_log=[], score_dict={})
    def get_state(self):
        return ControllerState(prompt='x', budget_left=self.budget_left, active_particle_ids=[p.id for p in self._particles.values() if p.status=='active'], completed_particle_ids=[p.id for p in self._particles.values() if p.status=='completed'], pruned_particle_ids=[p.id for p in self._particles.values() if p.status=='pruned'], particles={pid: ParticleSummary(id=p.id,time=p.time,parent_id=p.parent_id,source_anchor_id=p.source_anchor_id,nfe_used=p.nfe_used,status=p.status,last_preview_id=p.last_preview_id,num_children=p.num_children) for pid,p in self._particles.items()}, previews=dict(self._previews), event_log=[])

controller=OptimalController()
for beta in [0.0,0.25,0.5,0.75,1.0]:
    env=FakeEnv()
    ans=controller.solve(env,beta)
    print(beta, ans.nfe_used, ans.rule, ans.reward)
